// Renderizador único das artes: usado pelo motor (Playwright) e pelo editor do painel (iframe).
// Assim o que se vê no editor é exatamente o que sai no PNG final.
// Estilo pro: fontes de título (Anton, Bebas, Oswald...), faixas de destaque, contorno, brilho, ícones SVG,
// efeitos de luz (glows, vinheta, granulado), tratamento de cor da foto, objetos na frente do texto,
// desfoque de profundidade e carrossel panorâmico (fundo e objetos atravessando de um slide para o outro).
const CX_OK = ['alta', 'baixa', 'frase', 'titulo', 'normal'];
const CX_SIGLAS = new Set(['IA', 'SEO', 'CTA', 'CRM', 'ROI', 'KPI', 'PDF', 'UX', 'UI', 'API', 'PIX', 'CNPJ', 'CPF', 'MEI', 'ERP', 'SP', 'RJ', 'USD', 'BR', 'TV', 'FAQ', 'SMS', 'WhatsApp'.toUpperCase()]);
const CX_PEQ = new Set(['a', 'as', 'o', 'os', 'um', 'uma', 'de', 'da', 'das', 'do', 'dos', 'e', 'em', 'no', 'na', 'nos', 'nas', 'por', 'para', 'com', 'ou', 'ao', 'aos', 'à', 'às', 'que', 'se', 'é', 'são']);
// caixa do texto: alta (MAIÚSCULAS), baixa (minúsculas), frase (só a 1ª letra maiúscula), titulo (Cada Palavra Maiúscula), normal (como foi escrito)
export function aplicaCaixa(s, cx) {
  s = String(s ?? ''); if (!cx || cx === 'normal' || !CX_OK.includes(cx)) return s;
  const tk = []; let t = s.replace(/\[i:[a-z-]+\]/g, m => { tk.push(m); return '\u0001' + (tk.length - 1) + '\u0001'; });
  if (cx === 'alta') t = t.toUpperCase();
  else if (cx === 'baixa') t = t.toLowerCase();
  else {
    // sigla (IA, SEO, CTA) escrita em maiúsculas no meio de um texto normal continua como está; texto todo em maiúsculas é convertido por inteiro
    const todoAlto = !(/\p{Ll}/u.test(t)), poeBaixa = w => (CX_SIGLAS.has(w) || (!todoAlto && /^[A-Z0-9]{2,5}$/.test(w) && /[A-Z]/.test(w)) ? w : w.toLowerCase());
    t = t.replace(/[\p{L}\p{M}\d]+/gu, poeBaixa);
    if (cx === 'frase') t = t.replace(/(^|[.!?…]\s+|[.!?…]\|)([^\p{L}]*)(\p{L})/gu, (m, a, b, c) => a + b + c.toUpperCase()).replace(/^([^\p{L}]*)(\p{L})/u, (m, a, b) => a + b.toUpperCase());
    else { let i = 0; t = t.replace(/(^|[\s|*("“'\-\/])(\p{L}[\p{L}\p{M}]*)/gu, (m, a, w) => { const first = i++ === 0; return a + (!first && CX_PEQ.has(w) ? w : w[0].toUpperCase() + w.slice(1)); }); }
  }
  return t.replace(/\u0001(\d+)\u0001/g, (m, n) => tk[+n]);
}
export const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
// "|" quebra a linha, *palavra* vai na cor de destaque e [i:nome] põe um ícone num círculo da cor de destaque no meio do texto
export const rich = v => esc(v).split('|').map(l => l.replace(/\*([^*]+)\*/g, '<em>$1</em>').replace(/\[i:([a-z-]+)\]/g, (m, n) => ICONES[n] ? `<span class="ic" style="display:inline-flex;align-items:center;justify-content:center;width:.86em;height:.86em;border-radius:50%;background:var(--hl);color:var(--hlc,#0a0a0a);vertical-align:-.06em;margin-left:-.1em;position:relative;z-index:2;box-shadow:0 0 .4em rgba(0,0,0,.35)"><svg viewBox="0 0 24 24" width="58%" height="58%" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round">${ICONES[n]}</svg></span>` : '')).join('<br>');
const pct = v => (Math.max(-5, Math.min(6, Number(v))) * 100).toFixed(2) + '%';
export const roles = W => ({
  title:  { size: Math.round(W * .088), weight: 800, ls: '-.035em', lh: 1.04, w: .86 },
  body:   { size: Math.round(W * .042), weight: 500, ls: '-.01em',  lh: 1.28, w: .82 },
  number: { size: Math.round(W * .30),  weight: 800, ls: '-.06em',  lh: .9,   w: .86 },
  badge:  { size: Math.round(W * .026), weight: 700, ls: '.14em',   lh: 1.1,  w: .7 },
  cta:    { size: Math.round(W * .038), weight: 700, ls: '-.01em',  lh: 1.1,  w: .7 },
  label:  { size: Math.round(W * .030), weight: 500, ls: '.32em',   lh: 1.2,  w: .8 },
  footer: { size: Math.round(W * .021), weight: 500, ls: '0',       lh: 1.3,  w: .5 }
});
